            <hr />

            <div class="mb-4">
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif"
                           checked="@_editEmailNotifications"
                           @onchange="e => _editEmailNotifications = (bool)e.Value!" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif"
                           checked="@_editPushNotifications"
                           @onchange="e => _editPushNotifications = (bool)e.Value!" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest"
                           checked="@_editWeeklyDigest"
                           @onchange="e => _editWeeklyDigest = (bool)e.Value!" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>
            </div>

            <h6>Muted Channels</h6>
            <div class="channel-list mb-4">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _editMutedChannels.Contains(channel);
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="ch-@channel"
                               checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="ch-@channel">
                            @channel <span class="badge bg-secondary ms-1">@(isMuted ? "muted" : "active")</span>
                        </label>
                    </div>
                }
            </div>

            <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Preferences
            </button>
        </div>;
}

@* ───── Security Section ───── *@
@{
    RenderFragment RenderSecurity() =>
        @<div class="settings-section">
            <h4>Security</h4>
            <p class="text-muted">Manage your password, two-factor authentication, and active sessions.</p>
            <hr />

            @* Change Password *@
            <div class="card mb-4">
                <div class="card-header d-flex justify-content-between align-items-center"
                     style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>🔑 Change Password</span>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </div>
                @if (_passwordPanelOpen)
                {
                    <div class="card-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                        @if (_security?.LastPasswordChange is not null)
                        {
                            <small class="text-muted ms-3">
                                Last changed: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                            </small>
                        }
                    </div>
                }
            </div>

            @* Two-Factor *@
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <strong>Two-Factor Authentication</strong>
                        <span class="badge ms-2 @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch m-0">
                        <input class="form-check-input" type="checkbox"
                               checked="@_twoFactorEnabled"
                               @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                    </div>
                </div>
            </div>

            @* Active Sessions *@
            <h6>Active Sessions</h6>
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_security is not null)
                        {
                            @foreach (var session in _security.Sessions)
                            {
                                var isCurrent = session.Id == _security.Sessions.FirstOrDefault()?.Id;
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (isCurrent)
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => PromptRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @* Revoke Confirmation Dialog *@
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop-custom">
                    <div class="modal-dialog-custom">
                        <div class="card">
                            <div class="card-body">
                                <h5 class="card-title">Revoke Session</h5>
                                <p>
                                    Are you sure you want to revoke the session on
                                    <strong>@_sessionToRevoke.Device</strong>
                                    from <strong>@_sessionToRevoke.Location</strong>?
                                </p>
                                <div class="d-flex gap-2 justify-content-end">
                                    <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">
                                        Cancel
                                    </button>
                                    <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                        Revoke
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ───── Appearance Section ───── *@
@{
    RenderFragment RenderAppearance() =>
        @<div class="settings-section">
            <h4>Appearance</h4>
            <p class="text-muted">Customize how the application looks and feels.</p>
            <hr />

            <div class="row">
                <div class="col-md-6">
                    @* Theme *@
                    <div class="mb-4">
                        <h6>Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="theme-@theme" value="@theme"
                                       checked="@(_editTheme == theme)"
                                       @onchange="() => _editTheme = theme" />
                                <label class="form-check-label" for="theme-@theme">@theme</label>
                            </div>
                        }
                    </div>

                    @* Font Size *@
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="fs-@size" value="@size"
                                       checked="@(_editFontSize == size)"
                                       @onchange="() => _editFontSize = size" />
                                <label class="form-check-label" for="fs-@size">@size</label>
                            </div>
                        }
                    </div>

                    @* Language *@
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" @bind="_editLanguage">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode"
                                   checked="@_editCompactMode"
                                   @onchange="e => _editCompactMode = (bool)e.Value!" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Save
                    </button>
                </div>

                @* Live Preview *@
                <div class="col-md-6">
                    <h6>Preview</h6>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">
                            <strong>Dashboard</strong>
                        </div>
                        <div class="preview-body">
                            <p class="preview-text">This is a preview of your selected appearance settings.</p>
                            <div class="preview-card">
                                <span>Sample Card</span>
                            </div>
                            <div class="preview-card">
                                <span>Another Card</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>;
}

@code {
    // ── Section navigation ──
    private record SectionDef(string Key, string Label, string Icon);

    private readonly SectionDef[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private bool _saving;

    // ── Toast ──
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // ── Profile state ──
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // ── Notification state ──
    private string _editDisplayNameNotif = "";
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = [];
    private readonly string[] _allChannels = ["general", "announcements", "marketing", "engineering", "design"];

    // ── Security state ──
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var secTask = SettingsService.GetSecuritySettingsAsync();
        var appearTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, secTask, appearTask);

        // Profile
        _savedProfile = profileTask.Result;
        PopulateProfileFields(_savedProfile);

        // Notifications
        var notif = notifTask.Result;
        _editEmailNotifications = notif.EmailNotifications;
        _editPushNotifications = notif.PushNotifications;
        _editWeeklyDigest = notif.WeeklyDigest;
        _editMutedChannels = new List<string>(notif.MutedChannels);

        // Security
        _security = secTask.Result;
        _twoFactorEnabled = _security.TwoFactorEnabled;

        // Appearance
        var appear = appearTask.Result;
        _editTheme = appear.Theme;
        _editFontSize = appear.FontSize;
        _editLanguage = appear.Language;
        _editCompactMode = appear.CompactMode;
    }

    // ── Profile ──

    private void PopulateProfileFields(UserProfile profile)
    {
        _editDisplayName = profile.DisplayName;
        _editEmail = profile.Email;
        _editAvatarUrl = profile.AvatarUrl;
        _editBio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _saving = false;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            PopulateProfileFields(_savedProfile);
    }

    // ── Notifications ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!muted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        var prefs = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, new List<string>(_editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        await ShowToast("Notification preferences saved.");
    }

    // ── Security ──

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", isError: true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", isError: true);
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _saving = false;
        await ShowToast("Password updated successfully.");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;

        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        _saving = false;
        await ShowToast("Session revoked.");
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance ──

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        await ShowToast("Appearance settings saved.");
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_editTheme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_editFontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-sm",
            "large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_editCompactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    // ── Toast helper ──

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }
}

