+    to   { opacity: 1; transform: translateY(0); }
+}
+
+/* ── Modal backdrop ── */
+.modal-backdrop-custom {
+    position: fixed;
+    top: 0; left: 0; right: 0; bottom: 0;
+    background: rgba(0,0,0,0.4);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1040;
+}
+
+.modal-dialog-custom {
+    width: 100%;
+    max-width: 440px;
+}
+
+.modal-dialog-custom .card {
+    box-shadow: 0 8px 30px rgba(0,0,0,0.2);
+}
+
+/* ── Live Preview ── */
+.live-preview {
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    overflow: hidden;
+    transition: all 0.2s ease;
+}
+
+.preview-header {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.preview-body {
+    padding: 1rem;
+}
+
+.preview-text {
+    margin-bottom: 0.75rem;
+}
+
+.preview-card {
+    padding: 0.6rem 0.9rem;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    margin-bottom: 0.5rem;
+}
+
+/* Theme variants */
+.preview-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-light .preview-header {
+    background: #f8f9fa;
+}
+
+.preview-dark {
+    background: #1e1e2e;
+    color: #cdd6f4;
+    border-color: #45475a;
+}
+
+.preview-dark .preview-header {
+    background: #181825;
+    border-color: #45475a;
+}
+
+.preview-dark .preview-card {
+    border-color: #45475a;
+    background: #313244;
+}
+
+.preview-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
+    color: #212529;
+}
+
+.preview-system .preview-header {
+    background: #f0f0f0;
+}
+
+/* Font sizes */
+.preview-font-sm { font-size: 0.8rem; }
+.preview-font-md { font-size: 0.95rem; }
+.preview-font-lg { font-size: 1.15rem; }
+
+/* Compact mode */
+.preview-compact .preview-header { padding: 0.4rem 0.75rem; }
+.preview-compact .preview-body { padding: 0.5rem 0.75rem; }
+.preview-compact .preview-card { padding: 0.3rem 0.6rem; margin-bottom: 0.3rem; }
+.preview-compact .preview-text { margin-bottom: 0.4rem; }
+

